window.MONSTER_CHUNK_80 = [{"name":"Baregara","cr":12,"xp":19200,"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","evil","extraplanar"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":25,"ac_touch":13,"ac_flat_footed":21,"ac_mods":"+4 Dex, +12 natural, -1 size","hp":168,"hd":"16d10+80","hdvalue":16,"fort":15,"ref":14,"will":10,"dr":"10/good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":23,"speed":[{"type":"land","speed":30},{"type":"climb","speed":40}],"melee":"bite +23 (1d8+8), 2 claws +23 (1d10+8 plus grab), gore +23 (1d8+8)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"devouring grapple"},{"type":"monstrous challenge"},{"type":"onearmed hold"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"dispel magic"},{"spell":"teleport","details":"self plus 50 lbs. of objects only"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 4, 1d4 dire apes 50% or 1d2 girallons 35%"},{"spell":"unholy blight"}]},{"frequency":"3/day","spells":[{"spell":"quickened hold person"}]}],"strength":26,"dexterity":19,"constitution":20,"intelligence":15,"wisdom":16,"charisma":17,"baseatk":16,"cmb":25,"cmb_special":"+4 vs. grapple","cmd":39,"feats":[{"feat":"Critical Focus"},{"feat":"Improved Initiative"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (hold person)"},{"feat":"Step Up"},{"feat":"Throw Anything"}],"skills":[{"skill":"Acrobatics","value":15},{"skill":"Bluff","value":14},{"skill":"Climb","value":27},{"skill":"Diplomacy","value":11},{"skill":"Intimidate","value":30},{"skill":"Knowledge (nature)","value":10},{"skill":"Knowledge (planes)","value":13},{"skill":"Perception","value":22},{"skill":"Sense Motive","value":14},{"skill":"Stealth","value":19},{"skill":"Survival","value":19},{"skill":"Swim","value":16}],"languages":["Abyssal","Celestial","Common","Draconic","telepathy 100 ft."],"environments":["warm forests (Abyss)"],"organizations":["solitary","pair","troop (3-5)"],"treasure":"standard","description_visual":"This lumbering apelike monster has blood-red fur, twisted horns, and a hideous fanged orifice set in the center of its chest.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Devouring Grapple","kind":"Ex","details":"The mouth at the center of a baregara's chest automatically deals 2d8+4 points of damage per round to any creature the baregara successfully grapples."},{"type":"Monstrous Challenge","kind":"Su","details":"As a standard action, a baregara can make an Intimidate check to demoralize an opponent. If this check is successful, the baregara surges with power and gains a +4 enhancement bonus to Strength and Constitution for 10 minutes. This ability is usable three times per day."},{"type":"One-Armed Hold","kind":"Ex","details":"A baregara's huge arms allow it to initiate and maintain a grapple without the standard -4 penalty for not having both hands free."}],"description":"Although natives of the Abyss that often serve as minions for powerful demons or demon lords, baregaras are not in fact demons themselves. Some scholars classify them as \"proto-demons\"-monsters like bebiliths or xacabras that could perhaps someday complete their supernatural evolution into full demonic glory, but that have not quite yet reached that end. Of course, to the baregara's victims, these debates are incidental. In the Abyss, baregaras form small troops just like the apes of the Material Plane. These troops are led by the strongest fighter or an individual anointed by a powerful demon the baregara troop serves. Rivalries between troops are part of a complex hierarchy that is all but incomprehensible to non-baregaras, but planar scholars have observed that all baregaras take trophies from notable kills, and that these grisly mementos play some role in establishing the convoluted social standing of the troop leaders and their followers. Even when knuckle-walking on their enormous hands, baregaras stand over 12 ft. high when measured to the top of their horns, and their dense bodies can weigh up to 1,500 pounds.","ecology":"","habitat_society":""},{"name":"Basilosaurus","cr":12,"xp":19200,"alignment":"N","size":"Gargantuan","type":"animal","init":5,"senses":[{"type":"blindsense","modifier":"60 ft."},{"type":"low-light vision"}],"ac":27,"ac_touch":7,"ac_flat_footed":26,"ac_mods":"+1 Dex, +20 natural, -4 size","hp":161,"hd":"17d8+85","hdvalue":17,"fort":17,"ref":11,"will":7,"speed":[{"type":"swim","speed":40}],"melee":"bite +23 (4d6+15/19-20 plus grab), tail slap +18 (2d8+7)","space":"20 ft.","reach":"20 ft.","special_attacks":[{"type":"swallow whole","details":"4d6+15 bludgeoning damage, AC 20, 16 hp"}],"strength":41,"dexterity":12,"constitution":21,"intelligence":2,"wisdom":11,"charisma":6,"baseatk":12,"cmb":31,"cmd":42,"feats":[{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Vital Strike"}],"skills":[{"skill":"Perception","value":25},{"skill":"Swim","value":31}],"sq":[{"type":"hold breath"}],"environments":["any oceans"],"organizations":["solitary","pair","pod (3-10)"],"treasure":"none","description_visual":"This immense primeval whale has a sleek body that looks more serpentine than mammal, and jaws filled with sharp teeth.","group":"Megafauna","source":"PFRPG Bestiary 3","description":"Despite their saurian name, basilosauruses are in fact oceanic mammals, and at 60 ft. in length are highly formidable beasts of the sea. In appearance, they resemble greatly elongated whales, but with long, toothed jaws resembling an alligator's. Inexperienced observers often confuse a basilosaurus with a sea serpent or water orm—and in all fairness, in the aftermath of a basilosaurus attack on an unsuspecting ship, such distinctions are largely academic anyway.\n\nA basilosaurus relies as much on vision as echolocation to find prey, but sometimes mistakes smaller ships for food. Basilosauruses have few natural predators; only supernatural monsters like krakens, thalassic behemoths, and the largest of sea serpents can truly threaten a fully grown one.","ecology":"","habitat_society":""},{"name":"Blue Whale","cr":12,"xp":19200,"alignment":"N","size":"Colossal","type":"animal","init":-1,"senses":[{"type":"low-light vision"}],"ac":26,"ac_touch":1,"ac_flat_footed":26,"ac_mods":"-1 Dex, +25 natural, -8 size","hp":184,"hd":"16d8+112","hdvalue":16,"fort":17,"ref":9,"will":8,"speed":[{"type":"swim","speed":40}],"melee":"tail slap +21 (8d6+24 plus stun)","space":"30 ft.","reach":"30 ft.","special_attacks":[{"type":"capsize"},{"type":"swallow whole","details":"4d6+16 damage, AC 22, 18 hp"}],"strength":42,"dexterity":8,"constitution":25,"intelligence":2,"wisdom":13,"charisma":6,"baseatk":12,"cmb":36,"cmd":45,"cmd_special":"can't be tripped","feats":[{"feat":"Awesome Blow"},{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Improved Bull Rush"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (tail slap)"}],"skills":[{"skill":"Perception","value":27},{"skill":"Swim","value":35}],"sq":[{"type":"hold breath"}],"environments":["any oceans"],"organizations":["solitary","pair","pod (3-18)"],"treasure":"none","description_visual":"This massive aquatic mammal has bluish-gray coloration, a wide fluke tail, and a wide mouth filled with layers of baleen.","group":"Cetacean","source":"AP 59","special_abilities":[{"type":"Hold Breath","kind":"Ex","details":"A blue whale can hold its breath a number of rounds equal to 10 times its Constitution score before it risks drowning."},{"type":"Powerful Tail","kind":"Ex","details":"A blue whale's massive tail deals more damage than a normal tail slap. The blue whale's tail slap is a primary attack and applies 1-1/2 times its Strength bonus to its tail slap damage."},{"type":"Stun","kind":"Ex","details":"A blue whale's fluke can deliver a powerful stunning blow. A creature struck by this attack must succeed at a DC 34 Fortitude save or be dazed for 1 round. If the strike is a critical hit and the target fails its save, it is instead stunned for 1d4 rounds. The save DC is Strength-based."}],"description":"The imposing blue whale is one of the largest animals in the sea, though it is generally docile toward anything it doesn't perceive as a threat. A filter-feeder, the blue whale doesn't look at humans or ships as potential meals, instead preferring to eat millions of tiny invertebrates known as krill, which it sucks through its baleen in massive gulps. The most dangerous thing about a blue whale, other than its sheer size, is its powerful tail, which can capsize boats and kill humanoids. These enormous mammals can be found in all of Golarion's oceans and seas. An adult blue whale is 100 ft. long and weighs 200 tons.","ecology":"","habitat_society":""},{"name":"Calikang","cr":12,"xp":19200,"alignment":"LN","size":"Large","type":"monstrous humanoid","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"true seeing"}],"ac":27,"ac_touch":11,"ac_flat_footed":25,"ac_mods":"+2 Dex, +12 natural, +4 shield, -1 size","hp":157,"hd":"15d10+75","hdvalue":15,"hp_mods":["fast healing 5"],"fort":12,"ref":11,"will":11,"defensive_abilities":["defensive slam","energy absorption","suspend animation"],"immunities":["electricity","mind-affecting effects","negative energy"],"sr":23,"speed":[{"type":"land","speed":30}],"melee":"+1 longsword +18 (2d6+8/17-20), +1 longsword +18 (2d6+8/17-20), 4 slams +16 (1d6+3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"breath weapon","details":"60-foot line, 14d6 energy damage, Reflex DC 22 half, usable 1/day"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"magic weapon"},{"spell":"true seeing"},{"spell":"water walk"}]},{"frequency":"1/day","spells":[{"spell":"chain lightning"}]},{"frequency":"3/day","spells":[{"spell":"lightning bolt"}]}],"strength":25,"dexterity":15,"constitution":20,"intelligence":8,"wisdom":14,"charisma":17,"baseatk":15,"cmb":23,"cmd":35,"feats":[{"feat":"Critical Focus"},{"feat":"Double Slice"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (longsword)"},{"feat":"Improved Initiative"},{"feat":"Staggering Critical"},{"feat":"Two-Weapon Fighting"},{"feat":"Vital Strike"}],"skills":[{"skill":"Intimidate","value":21},{"skill":"Perception","value":20},{"skill":"Use Magic Device","value":18}],"languages":["Common","Giant"],"environments":["temperate hills","tropical hills"],"organizations":["solitary","gang (2-4)","tribe (5-12)"],"treasure":"standard (2 +1 longswords plus other treasure)","description_visual":"This blue-skinned, six-armed giant lurches to life, its armor and twin swords glittering with jewels.","source":"Inner Sea World Guide","special_abilities":[{"type":"Defensive Slam","kind":"Ex","details":"A calikang gains a cumulative +1 shield bonus to its AC for each of its arms that doesn't wield a manufactured weapon, to a maximum of +4 for four hands. A calikang can make slam attacks with these arms without losing this AC bonus."},{"type":"Energy Absorption","kind":"Su","details":"A spell that inflicts energy damage that is defeated by the calikang's SR or immunity to electricity is absorbed into its body, healing it for an amount of damage equal to the absorbed spell's caster level and granting an additional daily use of its breath weapon."},{"type":"Breath Weapon","kind":"Su","details":"A calikang can choose what kind of energy damage its breath weapon inflicts when it uses this ability, choosing from acid, cold, electricity, fire, or sonic energy. Calikangs are particularly adept at using electricity in this manner, and inflict 1 additional point of damage per die (+14 for most calikangs) when they elect to inflict electricity damage with their breath weapon."},{"type":"Suspend Animation","kind":"Su","details":"As a full-round action, a calikang can enter a state of suspended animation, freezing in place and becoming motionless. It remains aware of its surroundings. In this state, the calikang is immune to disease, inhaled toxins, poison, starvation, and thirst, and receives a +4 bonus on all Fortitude saves. The calikang can exit this state as an immediate action-if it does so to attack a foe or initiate combat, it gains a +4 insight bonus on its Initiative check."}],"description":"The calikang is a much sought-after guardian of treasuries, harems, and fortifications. Legend holds that, an untold number of eons ago, one of the thousand deities of Vudra failed at a task, and the first calikangs were born from that god's severed fingers. Calikangs have powerful sense of guilt and shame over their divine source's ancient failings, and they believe that if enough calikangs protect worldly holdings from robberies or destruction, this inherited sin will someday be wiped clean.\n\nCalikangs are 14 ft. tall and weigh 4,000 pounds. They can live for 200 years—though many extend their lives beyond this via suspended animation.","ecology":"","habitat_society":""},{"name":"Candlestone Courtier","cr":12,"xp":19200,"alignment":"NE","size":"Medium","type":"fey","init":9,"senses":[{"type":"low-light vision"},{"type":"see in darkness"}],"ac":26,"ac_touch":20,"ac_flat_footed":16,"ac_mods":"+9 Dex, +1 dodge, +4 natural, +2 shield","hp":161,"hd":"19d6+95","hdvalue":19,"fort":11,"ref":20,"will":14,"dr":"10/cold iron","sr":23,"speed":[{"type":"land","speed":30}],"space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"spellthrust"}],"spell_like_abilities_caster_level":19,"spell_like_abilities_concentration":24,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"misdirection"},{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"disfiguring touch"},{"spell":"disguise self"},{"spell":"faerie fire"},{"spell":"touch of idiocy"},{"spell":"whispering wind"}]},{"frequency":"1/day","spells":[{"spell":"ethereal jaunt"},{"spell":"phantom steed"},{"spell":"shadow walk"}]},{"frequency":"3/day","spells":[{"spell":"excruciating deformation"},{"spell":"major image"},{"spell":"sands of time"}]}],"strength":16,"dexterity":29,"constitution":20,"intelligence":16,"wisdom":17,"charisma":23,"baseatk":9,"cmb":12,"cmb_special":"+4 vs. trip","cmd":32,"cmd_special":"+2 vs. trip","feats":[{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Greater Trip"},{"feat":"Improved Trip"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (rapier)"},{"feat":"Whirlwind Attack"}],"skills":[{"skill":"Acrobatics","value":30},{"skill":"Bluff","value":27},{"skill":"Diplomacy","value":15},{"skill":"Disguise","value":20},{"skill":"Escape Artist","value":20},{"skill":"Knowledge (dungeoneering, history, local, nature, nobility, planes)","value":10},{"skill":"Perception","value":25},{"skill":"Perform (dance)","value":15},{"skill":"Sense Motive","value":15},{"skill":"Sleight of Hand","value":15},{"skill":"Stealth","value":30},{"skill":"Use Magic Device","value":28}],"languages":["Aklo","Common","Sylvan","Terran","Undercommon"],"sq":[{"type":"fey bargain"}],"environments":["any underground (Darklands)"],"organizations":["solitary","pair","delegation (3-6)"],"treasure":"standard (+1 keen rapier, +1 buckler)","description_visual":"This willowy, lavender-skinned stranger looks like he is dressed for an extravagant ball, and carries himself with a dancer's grace.","source":"Andoran Birthplace Of Freedom","special_abilities":[{"type":"Fey Bargain","kind":"Su","details":"Once per week, a Candlestone courtier can grant a limited wish or a permanent +2 inherent bonus to one ability score. In exchange, the bargainer is cursed to be carried off in its dreams each night by the courtier to a never-ending fey ball that, while pleasant as often as not, affects the dreamer as nightmare, requiring a saving throw each night (Will DC 21 negates). The DC to remove this curse is reduced by 4 if the courtier is killed, and a successful coup de grace on the courtier with a cold iron weapon automatically ends the curse. Ending the curse also ends any noninstantaneous effects of the bargain. A creature can have only one fey bargain at a time."},{"type":"Spellthrust","kind":"Su","details":"When a courtier threatens a critical hit, it can trigger a spell-like ability with a range of touch against the target. If the critical hit is confirmed, the target must save twice, using the lower result."}],"description":"Candlestone courtiers are emissaries of Queen Frilogarma and the Court of Ether. Venturing up from their Darklands domain, they make deals to the benefit of their queen, forge secret alliances with citizens of foreign lands, and inveigle mortals into endless revels in the inverted fey city while sapping the vitality of their victims to sate their alien appetites. Candlestone courtiers prefer to employ trickery and extortion over direct violence, but don't shy away from a fight if it is the fastest way to get what they want.","ecology":"","habitat_society":""},{"name":"Catoblepas","cr":12,"xp":19200,"alignment":"N","size":"Large","type":"magical beast","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["stench (30 ft., DC 23, 10 rounds)"],"ac":27,"ac_touch":8,"ac_flat_footed":27,"ac_mods":"-1 Dex, +19 natural, -1 size","hp":161,"hd":"14d10+84","hdvalue":14,"fort":15,"ref":8,"will":8,"sr":23,"speed":[{"type":"land","speed":40},{"type":"swim","speed":20}],"melee":"bite +18 (3d6+5), gore +18 (2d8+5/19-20), 2 hooves +16 (1d8+2)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"breath weapon","details":"60-ft. cone, poison, Fortitude DC 23, usable every 1d4 rounds"},{"type":"trample","details":"4d6+7, DC 22"}],"strength":20,"dexterity":8,"constitution":22,"intelligence":5,"wisdom":15,"charisma":10,"baseatk":14,"cmb":20,"cmd":29,"cmd_special":"+4 vs. trip","feats":[{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Improved Critical (gore)"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Multiattack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":25},{"skill":"Swim","value":13}],"languages":["Aklo"],"environments":["any swamps"],"organizations":["solitary","pair","herd (3-6)"],"treasure":"incidental","description_visual":"This ugly creature has a boar-like head with short antlers, a thick bullish body covered in spines, and cloven hooves on its stumpy legs.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Poison Breath","kind":"Ex","details":"A catoblepas's horrid, stinking breath is 60-foot cone of poison gas. Breath-contact; save Fort DC 23; frequency 1/ round for 6 rounds; effect 1d6 Con damage; cure 3 consecutive saves. The save DC is Constitution-based."}],"description":"The catoblepas is an aggressive beast at the best of times, willing to knock down trees, fences, even small houses to eat whatever it finds interesting, be that meal plant or animal or human being. Though it prefers swamps, the catoblepas has been known to forage in plains and forests for short periods before returning to the buoyant support of water and mud. Few creatures linger near a catoblepas's feeding ground because of the monster's bad temper and poisonous breath, and only rot-loving predators such as oozes or exceptionally large otyughs have any interest in hunting them.\n\nA catoblepas' primary motivation is hunting and exerting its dominance over lesser creatures in its territory. Easily detected by its foul odor, the creature tolerates the presence of wild animals, humanoid tribes, and even predators that it can bully as long as these things flee or act submissive when the poisonous brute lumbers into view. The catoblepas is known to engage in physical battles with other Large swamp creatures such as crocodiles or even froghemoths. Some humanoid tribes claim to know techniques to domesticate a catoblepas for use as a guard animal, but the monster's intractable nature and not insignificant intelligence almost certainly means magic is involved, as the creature has little need for alliances and can wipe out entire villages with its breath. Some have been known to use their breath underwater, creating a churning cloud of bubbles that kills fish in the area and starves out other creatures.\n\nA catoblepas's sense of smell is blunted by its own ungodly stench, and it can't easily recognize rival odors such as skunk musk (though this provides the beast no immunity to odor-based effects from other creatures).\n\nA catoblepas is 15 ft. long and weighs 2,200 pounds.","ecology":"","habitat_society":""},{"name":"Chernobue","cr":12,"xp":19200,"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","evil","extraplanar","qlippoth"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"auras":["misfortune (30 ft.)"],"ac":27,"ac_touch":13,"ac_flat_footed":23,"ac_mods":"+4 Dex, +14 natural, -1 size","hp":150,"hd":"12d10+84","hdvalue":12,"fort":15,"ref":10,"will":11,"dr":"10/lawful","immunities":["cold","poison","mind-affecting effects"],"resists":[{"type":"acid","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":23,"weaknesses":["light vulnerability"],"speed":[{"type":"land","speed":40}],"melee":"2 slams +19 (1d6+8/19-20 plus 1 Con damage), bite +19  (2d6+8 plus poison), 2 tentacles +14 (1d6+4)","space":"10 ft.","reach":"5 ft. (10 ft. with slams and tentacles)","special_attacks":[{"type":"horrific appearance","details":"DC 20"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"arcane sight"}]},{"frequency":"at-will","spells":[{"spell":"chaos hammer"},{"spell":"darkness"}]},{"frequency":"1/day","spells":[{"spell":"plane shift"}]},{"frequency":"3/day","spells":[{"spell":"confusion"},{"spell":"dispel magic"},{"spell":"protection from law"},{"spell":"quickened darkness"}]}],"strength":26,"dexterity":18,"constitution":24,"intelligence":13,"wisdom":17,"charisma":19,"baseatk":12,"cmb":21,"cmd":35,"cmd_special":"+4 vs. trip","feats":[{"feat":"Blind-Fight"},{"feat":"Improved Critical (slam)"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (darkness)"},{"feat":"Vital Strike"}],"skills":[{"skill":"Acrobatics","value":19,"special":"+23 jump"},{"skill":"Escape Artist","value":19},{"skill":"Intimidate","value":19},{"skill":"Knowledge (planes)","value":16},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":18},{"skill":"Stealth","value":15}],"languages":["Abyssal","telepathy 100 ft."],"environments":["any (Abyss)"],"organizations":["solitary","pair","gang (3-6)"],"treasure":"standard","description_visual":"This slippery, writhing mass of tentacles and stalked mouths has one huge hideous eye and a fanged maw for a belly.","group":"Qlippoth","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Aura of Misfortune","kind":"Su","details":"A chernobue radiates an aura of evil malaise to a radius of 30 ft. All lawful or good creatures in this area take a -1 penalty on attack rolls and weapon damage rolls. Lawful good creatures take a -3 penalty and upon first entering the aura must make a DC 20 Fortitude save or be sickened for as long as they remain in the area. This ability is Charisma-based."},{"type":"Horrific Appearance","kind":"Su","details":"Creatures that succumb to a chernobue's horrific appearance become paralyzed with disgust for 2d6 rounds; a paralyzed creature gets a new save each round to recover from the effect, provided he is no longer aware of the chernobue or within 30 ft. of it."},{"type":"Light Vulnerability","kind":"Ex","details":"A chernobue within an area of bright light takes 1 point of Constitution damage per minute it remains in the area."},{"type":"Poison","kind":"Su","details":"Bite-injury; save Fort DC 23; frequency 1/round for 6 rounds; effect 1d2 Con drain; cure 1 save. The thick, orange poison injected by a chernobue is semi-alive. As soon as the poisoned victim is cured of the poison (by making a save, being targeted with an effect like neutralize poison, or enduring the full duration of the poison), the orange fluid bursts from the victim's body, causing 1d6 Charisma damage and rendering the victim unconscious for 2d6 rounds unless he makes a final DC 23 Fortitude save. The save DC is Constitution-based."}],"description":"The chernobue is a living manifestation of the vile fecundity of the Abyss-a monstrous, alien pregnancy made flesh. By infecting creatures with the Abyssal taint they carry, they spread pain and misfortune wherever they flop and writhe-and with their plane shift ability, they are ready to spread their filth throughout the multiverse. A chernobue is 13 ft. long and weighs 500 pounds.","ecology":"","habitat_society":""},{"name":"Clockwork Golem","cr":12,"xp":19200,"alignment":"N","size":"Large","type":"construct","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":26,"ac_touch":10,"ac_flat_footed":25,"ac_mods":"+1 Dex, +16 natural, -1 size","hp":118,"hd":"16d10+30","hdvalue":16,"fort":5,"ref":6,"will":5,"dr":"10/adamantine","immunities":["construct traits","magic"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +23 (2d10+8 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"death burst"},{"type":"grind"},{"type":"wall of gears"}],"strength":27,"dexterity":12,"wisdom":11,"charisma":1,"baseatk":16,"cmb":25,"cmb_special":"+4 vs. grapple","cmd":36,"environments":["any"],"organizations":["solitary","gang (2-4)"],"treasure":"none","description_visual":"A vaguely humanoid shape made of metal lurches to life with the grinding whir and frantic ticking of hundreds of gears.","group":"Golem","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Death Burst","kind":"Ex","details":"When a clockwork golem is reduced to 0 or fewer hit points, it explodes in a shower of razor-sharp gears and debris. All creatures within a 10-foot burst take 12d6 points of slashing damage-a DC 18 Reflex save results in half damage. The save DC is Constitution-based."},{"type":"Grind","kind":"Ex","details":"A clockwork golem deals an additional 2d10+12 points of slashing damage when it makes a successful grapple check as razor-sharp gears and blades emerge from its body to grind and slice its foe."},{"type":"Immunity to Magic","kind":"Ex","details":"A clockwork golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against a clockwork golem, as noted below. • A grease spell cast on the golem causes it to move quickly for 1d6 rounds, as if under the effects of haste. • A rusting grasp spell deals damage to a clockwork golem normally, and makes the golem staggered for 1d6 rounds (no save)."},{"type":"Wall of Gears","kind":"Su","details":"As a standard action, a clockwork golem can fold into a whirling wall of grinding gears measuring 10 ft. by 10 ft. or 5 ft. by 20 ft. Anyone passing through the wall takes 15d6 points of slashing damage. If the wall appears in a creature's space, that creature can attempt a DC 18 Reflex save to leap to one side and avoid the damage entirely. The clockwork golem can take no actions while in this form except to resume its normal form as a move action. A clockwork golem's AC and immunities remain the same while it is in this form."}],"description":"Forged from thousands of gears, the clockwork golem is a precision creation. In combat, a clockwork golem is ruthlessly efficient, moving with swift conviction to grind and slice its foes to ribbons.\n\nConstruction\n\nA clockwork golem's body is made up of hundreds of carefully crafted copper, iron, and silver gears, weighing almost 1,500 pounds, and worth a total of 10,000 gp.\n\nCLOCKWORK GOLEM\n\nCL 15th; Price 120,000 gp\n\nConstruction\n\nRequirements Craft Construct, animate objects, blade barrier, geas/quest, grease, telekinesis, creator must be caster level 15th; Skill Craft (clocks) or Craft (locks) DC 20; Cost 65,000 gp","ecology":"","habitat_society":""},{"name":"Clockwork Leviathan","cr":12,"xp":19200,"alignment":"N","size":"Huge","type":"construct","subtypes":["clockwork"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":28,"ac_touch":14,"ac_flat_footed":22,"ac_mods":"+4 Dex, +2 dodge, +14 natural, -2 size","hp":128,"hd":"16d10+40","hdvalue":16,"fort":5,"ref":11,"will":5,"dr":"10/adamantine","immunities":["fire","construct traits"],"weaknesses":["vulnerable to electricity"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":60}],"melee":"bite +25 (2d6+11 plus grab), 2 slam +25 (1d8+11 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"breath weapon","details":"60-ft. line, 12d8 fire damage, Reflex DC 18 half, usable every 1d4 rounds, 3/day"},{"type":"grind"},{"type":"swallow whole","details":"2d8+16 slashing damage plus 2d6 fire damage, AC 17, 12 hp"}],"strength":33,"dexterity":18,"wisdom":11,"charisma":1,"baseatk":16,"cmb":29,"cmb_special":"+4 vs. grapple","cmd":45,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative","type":"bonus"},{"feat":"Lightning Reflexes","type":"bonus"}],"skills":[{"skill":"Stealth","value":8,"special":"+12 in water"},{"skill":"Swim","value":19}],"sq":[{"type":"swift reactions"},{"type":"winding"}],"environments":["any"],"organizations":["solitary","pod (2-4)"],"treasure":"none","description_visual":"Long and metallic, this serpentine construction resembles a mechanical eel with several paddle-like limbs.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A clockwork leviathan's breath weapon is a powerful jet of scorching steam-it functions equally well above and under water."},{"type":"Grind","kind":"Ex","details":"A clockwork leviathan deals an additional 1d8+16 points of slashing damage when it makes a successful grapple check because of the myriad twisting gears and churning pistons that make up its jagged underbelly."},{"type":"Swallow Whole","kind":"Ex","details":"A clockwork leviathan's interior is filled with injurious grinding gears and superheated water-in addition to taking damage, a swallowed creature must hold its breath or risk drowning as long as it remains inside a clockwork leviathan's \"stomach.\""}],"description":"Clockwork leviathans are equally capable of functioning on land and in water. Sailors who are haunted by the memories of these treacherous machines need not exaggerate their yarns, for the reality of an aquatic construct such as this holds enough terror in its story for even the hardiest of seafarers.\n\nA clockwork leviathan's numerous metal plates and links are made of such resilient material that they never rust, even after long exposure to the briny sea waters that leviathans often patrol.\n\nClockwork leviathans are 25 ft. long and weigh just over 3 tons.\n\nConstruction\n\nWhen creating these clockworks, great care must be taken to waterproof their components. The creator must start with crafted clockwork pieces worth 10,000 gp.\n\nCLOCKWORK LEVIATHAN\n\nCL 12th; Price 130,000 gp\n\nConstruction Requirements Craft Construct, freedom of movement, geas/quest, heat metal, and limited wish, creator must be at least caster level 12th; Skill Craft (clockwork) DC 20; Cost 70,000 gp","ecology":"","habitat_society":""},{"name":"Coloxus","cr":12,"xp":19200,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":13,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":26,"ac_touch":19,"ac_flat_footed":17,"ac_mods":"+9 Dex, +7 natural","hp":168,"hd":"16d10+80","hdvalue":16,"fort":15,"ref":19,"will":9,"dr":"10/good","immunities":["electricity","disease","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":23,"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"bite +25 (1d6+4 plus siphon), 2 slams +25 (1d4+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"droning wings"},{"type":"siphon"},{"type":"sneak attack","details":"+4d6"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"tongues"}]},{"frequency":"at-will","spells":[{"spell":"contagion"},{"spell":"invisibility"},{"spell":"suggestion"}]},{"frequency":"1/day","spells":[{"spell":"giant vermin"},{"spell":"shadow evocation"}]},{"frequency":"3/day","spells":[{"spell":"confusion"},{"spell":"haste"},{"spell":"mind fog"},{"spell":"quickened invisibility"}]}],"strength":19,"dexterity":28,"constitution":20,"intelligence":17,"wisdom":18,"charisma":23,"baseatk":16,"cmb":25,"cmd":39,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Reflexes"},{"feat":"Deceitful"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Quicken Spell-Like Ability (invisibility)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":28},{"skill":"Appraise","value":14},{"skill":"Bluff","value":29},{"skill":"Diplomacy","value":14},{"skill":"Disguise","value":19},{"skill":"Fly","value":26},{"skill":"Knowledge (arcana, history, planes, religion)","value":14},{"skill":"Perception","value":31},{"skill":"Sleight of Hand","value":17},{"skill":"Stealth","value":28}],"languages":["Abyssal","Celestial","Common","Infernal","telepathy 100 ft.","tongues"],"environments":["any urban (Abyss)"],"organizations":["solitary","pair","swarm (3-8)"],"treasure":"double","description_visual":"This figure would be the picture of elegance and refinement were it not for its grotesque fly head and shivering insectile wings.","group":"Demon","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Droning Wings","kind":"Ex","details":"Once per day, when it flutters its wings as a standard action, a coloxus can create a mesmerizing display of color and a sound-dampening buzzing drone. All creatures within 30 ft. that can see the coloxus must make a DC 24 Will save or be slowed for up to 6 rounds. Each subsequent round, the coloxus must take a swift action to maintain the effect or the effect ceases at the end of its turn. Additionally, the sound creates a buffer against sonic energy, granting the fly demon immunity to sonic attacks or effects while it continues to drone. The save DC is Charisma-based."},{"type":"Siphon","kind":"Su","details":"Any creature bitten by a coloxus must make a DC 23 Fortitude save or take 1d4 points of Charisma damage. A coloxus heals itself of 5 points of damage for every point of Charisma damage it deals. The save DC is Constitution-based."}],"description":"Coloxus demons, known also as fly demons, resemble humans with the head of a fly and twin pairs of gossamer wings. Even their smallest movements and gestures seem infused with manic quickness and alertness. A coloxus prefers to wear opulent clothing and jewels that would rival the wealthiest nobility of any race. A coloxus is 6 ft. tall and weighs 150 pounds.\n\nIronically-given their grotesque, insectile appearance-coloxus demons are demons of vanity. They are formed from the souls of narcissistic mortals responsible for disasters or tragedy through their careless self-absorption.\n\nDespite their foul appearance, coloxus demons consider themselves cultured and elite. They are unusually patient and well mannered for demons, and as a result are often used as emissaries, diplomats, and negotiators by marilith generals, balors, and even demon lords. Even when facing hated foes, coloxus demons are the epitome of courtesy, but such manners are always a deceitful veneer, masking the creatures' efforts to gain the upper hand.\n\nEvil mortal spellcasters are fond of conjuring coloxus demons for similar roles, but the monsters also work well as assassins. Even in this role, a coloxus is dignified and polite. Only when presented with a ref lection of itself does the normally civilized coloxus show its true demonic colors-any creature foolish enough to trick a coloxus into looking at a mirror finds herself the eternal foe of an insulted and scandalized demon.","ecology":"","habitat_society":""},{"name":"Dark Young of Shub-Niggurath","cr":12,"xp":19200,"alignment":"CE","size":"Huge","type":"aberration","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"30 ft."}],"auras":["frightful presence (30 ft., DC 24)"],"ac":27,"ac_touch":11,"ac_flat_footed":24,"ac_mods":"+3 Dex, +16 natural, -2 size","hp":161,"hd":"14d8+98","hdvalue":14,"fort":11,"ref":9,"will":0,"dr":"15/slashing","immunities":["acid","electricity","fire","poison"],"speed":[{"type":"land","speed":30}],"melee":"4 tentacles +19 (1d8+10/19-20 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"constrict","details":"1d8+10"},{"type":"sucking maws"},{"type":"trample","details":"1d8+15, DC 27"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"freedom of movement"}]},{"frequency":"at-will","spells":[{"spell":"air walk"},{"spell":"tree shape"}]},{"frequency":"1/day","spells":[{"spell":"insanity"},{"spell":"tree stride"}]},{"frequency":"3/day","spells":[{"spell":"command plants"},{"spell":"entangle"}]}],"strength":30,"dexterity":17,"constitution":24,"intelligence":16,"wisdom":19,"charisma":21,"baseatk":10,"cmb":1,"cmb_special":"+4 vs. grapple","cmd":13,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Critical (tentacles)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (tentacles)"}],"skills":[{"skill":"Knowledge (arcana)","value":17},{"skill":"Knowledge (nature)","value":17},{"skill":"Knowledge (religion)","value":17},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":18},{"skill":"Spellcraft","value":20},{"skill":"Stealth","value":12,"special":"+20 in forests"}],"languages":["Aklo"],"environments":["temperate forests","temperate swamps"],"organizations":["solitary","pair","grove (3-6)"],"treasure":"standard","description_visual":"The lumbering bulk of a treelike monster lurches out of the mist, its branches tentacles, its roots ending in hooves, and its trunk decorated with numerous drooling maws.","source":"AP 46","special_abilities":[{"type":"Sucking Maws","kind":"Su","details":"A dark young of Shub-Niggurath that successfully pins a creature it is grappling automatically inflicts 1d4 points of Strength drain on that creature. A DC 24 Fortitude save reduces this effect to 1 point of Strength drain. A creature drained to 0 Strength doesn't die, but must make a DC 24 Will save at that point to resist being driven mad by the experience, as the foul green waste exuded from the same sucking mouths that drink life implant in the emptied shells strange visions and horrifying certainties. If you use the GameMastery Guide in your game, this madness manifests as schizophrenia, but with a save DC equal to the dark young's Strength drain save DC listed above (DC 24 for most dark young). One common result of this unfortunate madness is a strange desire to return to the site of their original encounter in hopes of being consumed entirely by the creature that only drank a part of their body and mind-many of those who survive this horrific ordeal go on to found dark young cults of their own. If you don't use the GameMastery Guide in your game, treat this madness instead as an insanity spell. The madness element of a dark young's sucking maws is a mind-affecting effect. The save DC for all of the saving throws involved with this special ability is Constitution-based."}],"description":"The Elder God known in whispered circles as Shub- Niggurath is reputed to have a thousand young, when in fact her spawn are myriad. Yet some of her children are more fecund and successful than others, and the monstrosities known as her dark young are perhaps the best known of this legion of monstrosities.\n\nIn combat, a dark young usually starts by using entangle and command plants to seize control of the surrounding terrain-its ability to constantly use freedom of movement affords it mobility through such regions, allowing it to move through the areas and select its prey with ease.\n\nIntelligent and canny, dark young know that spell-casters are more difficult to affect with insanity, and save that spell-like ability for use against rogues, fighters, and similar foes. Flight offers no guarantee of safety from the dark young, for they can pursue their foes through the air as surely as across land.\n\nEcology A dark young superficially resembles a tree, and while it possesses magic that allows it some ability to appear as a tree or to control the plants of the trackless forests it favors, upon close inspection a dark young is manifestly something far more than a mere tree. Even the smallest of these creatures stand taller than a house, while the largest of them shake the very earth with their cloven hooves and crush cities and forests alike with their passage.\n\nA typical dark young of Shub-Niggurath stands nearly 30 ft. tall and weighs 12,000 pounds, but many are much larger. While most are encountered in temperate regions, they can also be found in subarctic or tropical forests.\n\nThese dark young appear no different than their temperatedwelling kin, but when they use their tree shape ability, they assume the forms of plants native to the region.\n\nHabitat & Society Dark young prefer to dwell in large wilderness regions, particularly within temperate woodlands or swamps.\n\nWhile their presence amid cults of Shub-Niggurath have given rise to assumptions that these foul lunatics possess strange secrets that allow them to conjure the dark young to serve their cabals as guardians, in fact the reverse is true. Cultists of Shub-Niggurath often seek out the dark young and offer themselves to the creatures in sacrifice, in hopes of either being transported to the embrace of their goddess Shub-Niggurath in the process of being digested or impressing the dark young with their devotion so they might be granted reincarnation as one of them-or simply out of madness. In most cases, these offerings end poorly for the cultist, for the dark young of Shub- Niggurath are ravenous-the numerous sucking mouths that stud their trunks drain blood, drink flesh, and devour life rapidly, causing the victim's body to wither and atrophy. Often, a dark young takes pains to avoid damaging those it grabs and holds against its hungry flanks, for a living, squirming meal is so much more delicious than a lifeless husk. Those drained to zero Strength by a dark young are sometimes left hideously alive, perhaps draped across high branches in a tree where the paralyzed victim has no choice but a slow death from thirst and exposure, or maybe left for hungrier jaws in the woods amid the cloven prints and pools of thick green waste that drain from these creatures as they feed.\n\nYet not all cultists who seek the dark young meet such ends, for some of the dark young have strange needs and uses for mortal minions. These dark young serve as objects of veneration and obsession for their cults, and happily accept their sacrifices in Shub-Niggurath's name, even though most dark young themselves feel no great debt of loyalty to their fecund progenitor. The actual uses the dark young put their cults to vary wildly-these aberrations are quite intelligent, and many have their own goals and plans that are made much easier to achieve with the addition of a blindly loyal cult. Most dark young merely enjoy the idea of being worshiped as a god, while others stand apart from their kin and do feel a strong link to Shub-Niggurath, seeing these cults as a way to honor their inhuman mother with mortal minions. Yet the dark young of Shub-Niggurath are the spawn of a body and mind alien to most forms of mortal life, and as such the majority of these monsters have plans and goals that may seem nonsensical at best (such as a strange desire to drive all avian life from a swamp, or a drive to build a series of stone menhirs in a massive spiral shape recognizable only from absurdly great heights) or wantonly destructive at worst (such as the destruction of all settlements within a mile of a forest's edge). It's rare for the cultists themselves to be privy to the dark young's reasoning, and most worshipers content themselves with their own interpretations of why they serve one of the Thousand Young.","ecology":"A dark young superficially resembles a tree, and while it possesses magic that allows it some ability to appear as a tree or to control the plants of the trackless forests it favors, upon close inspection a dark young is manifestly something far more than a mere tree. Even the smallest of these creatures stand taller than a house, while the largest of them shake the very earth with their cloven hooves and crush cities and forests alike with their passage.\n\nA typical dark young of Shub-Niggurath stands nearly 30 ft. tall and weighs 12,000 pounds, but many are much larger. While most are encountered in temperate regions, they can also be found in subarctic or tropical forests.\n\nThese dark young appear no different than their temperatedwelling kin, but when they use their tree shape ability, they assume the forms of plants native to the region.","habitat_society":"Dark young prefer to dwell in large wilderness regions, particularly within temperate woodlands or swamps.\n\nWhile their presence amid cults of Shub-Niggurath have given rise to assumptions that these foul lunatics possess strange secrets that allow them to conjure the dark young to serve their cabals as guardians, in fact the reverse is true. Cultists of Shub-Niggurath often seek out the dark young and offer themselves to the creatures in sacrifice, in hopes of either being transported to the embrace of their goddess Shub-Niggurath in the process of being digested or impressing the dark young with their devotion so they might be granted reincarnation as one of them-or simply out of madness. In most cases, these offerings end poorly for the cultist, for the dark young of Shub- Niggurath are ravenous-the numerous sucking mouths that stud their trunks drain blood, drink flesh, and devour life rapidly, causing the victim's body to wither and atrophy. Often, a dark young takes pains to avoid damaging those it grabs and holds against its hungry flanks, for a living, squirming meal is so much more delicious than a lifeless husk. Those drained to zero Strength by a dark young are sometimes left hideously alive, perhaps draped across high branches in a tree where the paralyzed victim has no choice but a slow death from thirst and exposure, or maybe left for hungrier jaws in the woods amid the cloven prints and pools of thick green waste that drain from these creatures as they feed.\n\nYet not all cultists who seek the dark young meet such ends, for some of the dark young have strange needs and uses for mortal minions. These dark young serve as objects of veneration and obsession for their cults, and happily accept their sacrifices in Shub-Niggurath's name, even though most dark young themselves feel no great debt of loyalty to their fecund progenitor. The actual uses the dark young put their cults to vary wildly-these aberrations are quite intelligent, and many have their own goals and plans that are made much easier to achieve with the addition of a blindly loyal cult. Most dark young merely enjoy the idea of being worshiped as a god, while others stand apart from their kin and do feel a strong link to Shub-Niggurath, seeing these cults as a way to honor their inhuman mother with mortal minions. Yet the dark young of Shub-Niggurath are the spawn of a body and mind alien to most forms of mortal life, and as such the majority of these monsters have plans and goals that may seem nonsensical at best (such as a strange desire to drive all avian life from a swamp, or a drive to build a series of stone menhirs in a massive spiral shape recognizable only from absurdly great heights) or wantonly destructive at worst (such as the destruction of all settlements within a mile of a forest's edge). It's rare for the cultists themselves to be privy to the dark young's reasoning, and most worshipers content themselves with their own interpretations of why they serve one of the Thousand Young."},{"name":"Derghodaemon","cr":12,"xp":19200,"alignment":"NE","size":"Large","type":"outsider","subtypes":["daemon","evil","extraplanar"],"init":5,"senses":[{"type":"all-around vision"},{"type":"darkvision","modifier":"60 ft."},{"type":"detect magic"},{"type":"see invisibility"}],"auras":["feeblemind (DC 20)"],"ac":27,"ac_touch":14,"ac_flat_footed":22,"ac_mods":"+5 Dex, +13 natural, -1 size","hp":161,"hd":"14d10+84","hdvalue":14,"fort":15,"ref":14,"will":8,"dr":"10/good","immunities":["acid","death effects","disease","poison"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":23,"speed":[{"type":"land","speed":40}],"melee":"5 claws +21 (1d6+8/19-20)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d8+12 plus 2 Con damage"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"},{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"}]},{"frequency":"1/day","spells":[{"spell":"creeping doom"},{"spell":"insect plague"},{"spell":"summon","details":"level 4, 1 derghodaemon 30%"}]},{"frequency":"3/day","spells":[{"spell":"fear"},{"spell":"quickened summon swarm"}]}],"strength":27,"dexterity":20,"constitution":22,"intelligence":7,"wisdom":17,"charisma":16,"baseatk":14,"cmb":13,"cmd":26,"feats":[{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Improved Critical (claws)"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (summon swarm)"},{"feat":"Sickening Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Intimidate","value":20},{"skill":"Perception","value":28},{"skill":"Sense Motive","value":20},{"skill":"Stealth","value":18}],"languages":["Abyssal","Draconic","Infernal","telepathy 100 ft."],"sq":[{"type":"swarmwalking"}],"environments":["any (Abaddon)"],"organizations":["solitary","infestation (2-6)"],"treasure":"standard","description_visual":"A deadly and vicious bouquet of insectile claws sprouts from this horrid, three-legged, multi-eyed beast.","group":"Daemon","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Feeblemind Aura","kind":"Su","details":"By grinding and clicking its mandibles and chitinous plates together (a free action), a derghodaemon can affect all creatures within 30 ft. as if by a feeblemind spell. Daemons are immune to this effect, but all other creatures must make a DC 20 Will save to resist the effects. A creature that makes this save is immune to the effect for 24 hours. A creature that fails remains affected as long as the derghodaemon continues to maintain the aura and the subject remains within 30 ft. of the derghodaemon. Once either condition ends, the victim of this effect can attempt a new DC 20 Will save once per minute to recover from the effect; otherwise, it can be cured by a heal, limited wish, miracle, or wish spell. A derghodaemon cannot use its spell-like abilities or rend attack in any round in which it uses its feeblemind aura. This is a sonic mind-affecting effect. The save DC is Charisma-based."},{"type":"Swarmwalking","kind":"Su","details":"A derghodaemon is immune to damage or distraction effects caused by swarms."}],"description":"These brutal daemons personify death resulting from violent insanity, such as being murdered by a maniac or torn to shreds by a pack of rabid predators. These insectoid creatures roam the Outer Planes, scavenging battlefields and following the inevitable trail of violence in those hostile worlds. They hunt the weak and dying along the fringe of battles, feeding off their victims' suffering until they make their kill. Attacks from a derghodaemon often come from within a cloud of biting insects.\n\nBrutish and low on intellect, derghodaemons find themselves serving as front-line fighters in fiendish armies. A derghodaemon stands 9 ft. tall and weighs 800 pounds.","ecology":"","habitat_society":""},{"name":"Diplodocus","cr":12,"xp":19200,"alignment":"N","size":"Colossal","type":"animal","init":6,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":25,"ac_touch":4,"ac_flat_footed":23,"ac_mods":"+2 Dex, +21 natural, -8 size","hp":190,"hd":"20d8+100","hdvalue":20,"fort":17,"ref":14,"will":4,"speed":[{"type":"land","speed":30}],"melee":"2 tail lashes +22 (4d6+15/19-20)","space":"30 ft.","reach":"60 ft.","special_attacks":[{"type":"trample","details":"2d8+22, DC 35"}],"strength":40,"dexterity":14,"constitution":21,"intelligence":2,"wisdom":17,"charisma":11,"baseatk":15,"cmb":8,"cmd":20,"feats":[{"feat":"Awesome Blow"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (tail lash)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Staggering Critical"}],"skills":[{"skill":"Perception","value":32}],"environments":["warm plains"],"organizations":["solitary","pair","herd (3-14)"],"treasure":"none","description_visual":"This enormous, long-necked quadruped moves with an uncanny grace, holding its lengthy, whiplike tail out level behind it.","group":"Dinosaur","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Tail Lash","kind":"Ex","details":"The diplodocus prefers to attack with its tail. The dinosaur can snap its incredibly long tail with surprising speed like an enormous whip-this is a primary attack that deals bludgeoning and slashing damage. A diplodocus can make two separate attacks with its tail lash as a full-attack action."}],"description":"The diplodocus is one of the longest dinosaurs, capable of reaching lengths of 100 ft. or more. Much of this length is taken up by the diplodocus's tremendously powerful whiplike tail, a devastating weapon capable of striking at a considerable range.","ecology":"","habitat_society":""},{"name":"Evaluator Robot","cr":12,"xp":19200,"alignment":"N","size":"Medium","type":"construct","subtypes":["robot"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"superior optics"}],"ac":27,"ac_touch":15,"ac_flat_footed":22,"ac_mods":"+5 Dex, +12 natural","hp":158,"hd":"16d10+20 (+50 force field)","hdvalue":16,"fort":5,"ref":10,"will":10,"defensive_abilities":["hardness 10"],"immunities":["construct traits"],"weaknesses":["vulnerable to critical hits and electricity"],"speed":[{"type":"land","speed":50},{"type":"fly","speed":120,"maneuverability":"perfect"}],"melee":"bastard sword +22 (1d10+6/19-20 plus stun)  or 2 slams +22 (1d4+6 plus stun)","ranged":"integrated laser rifle +21 ranged touch (4d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"memory wipe"},{"type":"stun","details":"DC 19, 1d4 rounds"}],"strength":22,"dexterity":21,"intelligence":12,"wisdom":17,"charisma":1,"baseatk":16,"cmb":22,"cmd":37,"feats":[{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Sense Motive)"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":17},{"skill":"Knowledge (local)","value":12},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":25},{"skill":"Stealth","value":10}],"languages":["Androffan","Common","process languages"],"environments":["any (Numeria)"],"organizations":["solitary"],"treasure":"none","description_visual":"With wings and an unearthly glow, this mechanical being could easily be mistaken for an angel.","group":"Robot","source":"AP 90","special_abilities":[{"type":"Force Field","kind":"Ex","details":"An evaluator robot is sheathed in a thin layer of shimmering energy that grants it 50 bonus hit points. All damage dealt to an evaluator robot with an active force field is deducted from these hit points first. As long as the force field is active, the evaluator robot is immune to critical hits. An evaluator robot's force field has fast healing 10, but once these hit points are reduced to 0, the force field shuts down and doesn't reactivate for 24 hours."},{"type":"Integrated Laser Rifle","kind":"Ex","details":"An evaluator robot has a built-in laser rifle. This weapon has a range of 150 ft. and deals 4d6 points of fire damage on a hit. The weapon can fire once per round as a ranged touch attack. A laser attack can pass through force fields and force effects, such as a wall of force, to strike a foe beyond without damaging that field. Objects like glass or other transparent barriers don't provide cover from lasers, but unlike force barriers, a transparent physical barrier still takes damage when a laser passes through it. Invisible creatures and objects are immune to damage from lasers. Fog, smoke, and other clouds provide cover in addition to concealment from laser attacks. Darkness (magical or otherwise) has no effect on lasers other than providing concealment."},{"type":"Memory Wipe","kind":"Ex","details":"As a standard action, an evaluator robot can make a touch attack that, if it hits, injects nanites into a target and erases the last 12 hours of its memories. A successful DC 19 Will save negates this effect. This is a mind-affecting effect, and the save DC is Intelligence-based."},{"type":"Process Languages","kind":"Ex","details":"Exceptional processing and data stores allows an evaluator robot to parse language in a way that lets it permanently speak and understand any spoken or written language it observes for at least 1 minute."},{"type":"Stun","kind":"Ex","details":"An evaluator robot's melee attacks deliver a nonlethal jolt of electricity with each strike. If the robot strikes a creature twice in one round with its bastard sword or slam attack, that target must succeed at a DC 19 Fortitude save or be stunned for 1d4 rounds. The save DC is Intelligence-based."},{"type":"Superior Optics","kind":"Ex","details":"An evaluator robot can see invisible creatures or objects as if they were visible."}],"description":"Androffans, the race responsible for the presence of robots on Golarion, were a spacefaring people who visited dozens of worlds. Masters of engineering, they created robots that could perform a wide array of tasks, even trusting their creations to perform complex surgeries on the Androffans' own organic forms. In the course of their interplanetary explorations, the Androffans quickly learned that not every world was ready to comprehend the awesome experience of leaving one's home planet to visit others. Not wanting to risk valuable crew members, the Androffans created evaluator robots as an alternative to sending a shuttle mission to alien planets and interacting in person. When sensors aboard Androffan ships orbiting foreign worlds discovered other humanoid species, evaluator robots would be dispatched to assess the planets' alien cultures.\n\nTaking forms designed to be recognizable to a planet's general populace, evaluator robots would drop from orbiting surveillance ships onto alien worlds to collect data so that their masters could determine the readiness of the planets' inhabitants to accept the existence of creatures from other worlds. Androffans also used evaluator robots to determine how violent or superstitious the indigenous populations were so that they could carefully plan direct contact. Evaluator robots were fashioned into pleasing and majestic forms to command respect and admiration from the humanoids they interacted with, and were usually made slightly taller than the planet's primary race so as to seem properly impressive. These robots' advanced construction utilizes sophisticated lightweight materials, making their durable frames weigh in under 400 pounds. The model presented here is the most common design-a radiant humanoid angel with gleaming feathers of brushed metal.\n\nDesign\n\nThe engineers who designed evaluator robots created each one to serve specific purposes tailored to the world it was intended to observe. These thematic designs were tested through trial and error by the evaluators themselves, who paid close attention to the religions encountered on each planet. They discovered that reverence for angelic beings was common on many worlds populated by sentient humanoids, so the engineers built the majority of evaluator robots in this form.\n\nAlthough some evaluators were designed for use on worlds that used advanced technology, evaluators were rarely used to observe cultures that had already reached space on their own or that were otherwise accustomed to dealing with beings from other worlds. In some cases, Androffan engineers designed evaluator robots to mimic the form of beings iconic to the populace, gathering information about these individuals from intercepted communication signals. This was often judged too risky, however, as it was found that cultures rarely responded well to the eventual revelation that their resurrected heroes and messiahs were actually alien robots.\n\nEven though redesigning an evaluator robot's outward form was simple, their complex programming required a vast amount of collected data. If the robot couldn't reply in a convincing manner, or if its memory-modifying nanites took no hold on the alien humanoids it encountered, then the evaluator's mission was quickly compromised. The robot's creators then had to hope that the interaction would be interpreted as a fluke supernatural experience, or that the witness would be disbelieved and derided by its community.\n\nEvaluator robots are universally curious, their programming filling them with an endless need to learn about living creatures. These robots take every opportunity to ask questions of intelligent organic life forms, especially humanoids. An evaluator robot compares these answers to profiles of existing cultures, either installed when it was created or assembled from previous interactions. Complex algorithms capable of parsing the nuances of myriad humanoid societies allow the robot to quickly evaluate and categorize the nature of a particular society using these hundreds or thousands of profiles. Once an evaluator has thoroughly assessed a planet's cultures, its Androffan masters use this information to plan a landing expedition to make direct contact.\n\nHabitat & Society\n\nAs robots, evaluators have no society outside of their programming, and their habitat is wherever they happen to be deployed. In the Inner Sea region, nearly all evaluator robots encountered to date have been found in Silver Mount.\n\nSince they were designed to interact with sentient organic beings, evaluator robots don't regularly associate with\n\nother robots unless tasked with a project requiring such interaction, and instead keep the company of humanoids (though their cold robotic presence isn't always comforting).\n\nCrafts that split from Divinity during its crash and fell to other parts of Numeria contained two other known evaluator robots. A tribe of Ghost Wolves destroyed one of these evaluators-designed to resemble a horned, red-skinned fiend-when it appeared before the Kellid barbarians in the Sellen Hills. The robot fought with wicked claws, and after it was destroyed, it exploded in a blast that killed dozens of the barbarians. The other evaluator, reportedly appearing as a six-armed, three-faced woman with bronze skin, was spotted brief ly by griffon riders at Castle Urion before it headed south into the River Kingdoms, and hasn't been seen since.","ecology":"","habitat_society":"As robots, evaluators have no society outside of their programming, and their habitat is wherever they happen to be deployed. In the Inner Sea region, nearly all evaluator robots encountered to date have been found in Silver Mount.\n\nSince they were designed to interact with sentient organic beings, evaluator robots don't regularly associate with\n\nother robots unless tasked with a project requiring such interaction, and instead keep the company of humanoids (though their cold robotic presence isn't always comforting).\n\nCrafts that split from Divinity during its crash and fell to other parts of Numeria contained two other known evaluator robots. A tribe of Ghost Wolves destroyed one of these evaluators-designed to resemble a horned, red-skinned fiend-when it appeared before the Kellid barbarians in the Sellen Hills. The robot fought with wicked claws, and after it was destroyed, it exploded in a blast that killed dozens of the barbarians. The other evaluator, reportedly appearing as a six-armed, three-faced woman with bronze skin, was spotted brief ly by griffon riders at Castle Urion before it headed south into the River Kingdoms, and hasn't been seen since."},{"name":"Forsaken Lich","cr":12,"xp":19200,"race":"Human lich","classes":[{"class":"cleric of Urgathoa","level":11}],"alignment":"NE","size":"Medium","type":"undead","subtypes":["augmented humanoid"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["delusory aura (100 ft.)"],"ac":21,"ac_touch":11,"ac_flat_footed":21,"ac_mods":"+7 armor, +1 deflection, +3 natural","hp":97,"hd":"11d8+44","hdvalue":11,"fort":7,"ref":3,"will":12,"defensive_abilities":["channel resistance +4","soul shield","spell storm"],"dr":"15/bludgeoning and magic","immunities":["cold","electricity","undead traits"],"speed":[{"type":"land","speed":20}],"melee":"+1 scythe +15 (2d4+8/19-20/x4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"9/day, DC 19, 6d6"},{"type":"disembodied strike","details":"1d8+5"},{"type":"hand of the acolyte","details":"8/day"},{"type":"soul lash","details":"DC 19; 5d6"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"dispelling touch"}]},{"frequency":"8/day","spells":[{"spell":"bleeding touch","details":"5 rounds"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":11,"spellsprepared_concentration":11,"spellsprepared":[{"spell_level":6,"spell_slots":1,"spells":[{"spell":"antilife shell"},{"spell":"create undead","type":"domain"}]},{"spell_level":5,"spell_slots":1,"spells":[{"spell":"flame strike"},{"spell":"slay living","type":"domain"},{"spell":"symbol of pain"},{"spell":"unhallow"}]},{"spell_level":4,"spell_slots":1,"spells":[{"spell":"divine power"},{"spell":"freedom of movement"},{"spell":"imbue with spell ability","type":"domain"},{"spell":"spell immunity"},{"spell":"unholy blight"}]},{"spell_level":3,"spell_slots":1,"spells":[{"spell":"animate dead","type":"domain"},{"spell":"bestow curse"},{"spell":"dispel magic"},{"spell":"glyph of warding"},{"spell":"invisibility purge"},{"spell":"protection from energy"}]},{"spell_level":2,"spell_slots":1,"spells":[{"spell":"death knell","type":"domain"},{"spell":"desecrate"},{"spell":"gentle repose"},{"spell":"hold person"},{"spell":"resist energy"},{"spell":"silence"}]},{"spell_level":1,"spell_slots":1,"spells":[{"spell":"cause fear","type":"domain"},{"spell":"command"},{"spell":"entropic shield"},{"spell":"deathwatch"},{"spell":"doom"},{"spell":"protection from good"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"read magic"}]}],"spelldomains":"Death, Magic","strength":20,"dexterity":10,"intelligence":13,"wisdom":21,"charisma":18,"baseatk":8,"cmb":13,"cmd":24,"feats":[{"feat":"Combat Expertise"},{"feat":"Craft Wondrous Item"},{"feat":"Extra Channel"},{"feat":"Improved Critical (scythe)"},{"feat":"Improved Trip"},{"feat":"Selective Channeling"},{"feat":"Weapon Focus (scythe)"}],"skills":[{"skill":"Knowledge (arcana)","value":15},{"skill":"Knowledge (religion)","value":15},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":19},{"skill":"Spellcraft","value":15}],"languages":["Common","Necril"],"sq":[{"type":"death's embrace"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This horribly withered creature moves in jerks and twitches as if constantly wracked with pain. Waves of shadow undulate through the creature's body, emerging like appendages from just beneath its dry, stretched skin.","source":"AP 48","description":"The means of attaining lichdom are extremely personal for mortal spellcasters, fraught with misinformation and peril. The smallest miscalculation in the potion of lichdom's formula or most minute flaw in one's phylactery can interrupt the process that infuses one's mortal soul with overwhelming arcane and negative energies. Other times, an inexperienced wizard attempts the\n\ntransformation, or erroneously consumes a formula produced for another spellcaster, instantly dying from the backlash of potent forces or condemning himself to a terminal but far more terrible end. In these sorrowful cases, the process traps the soul of the would-be lich outside a phylactery that will not accept it and a body that has rejected it. The potent arcane forces tampered with by the lich's failed creation also find themselves unleashed but uncontrolled, surrounding the newly formed abomination, empowering it but also slowly consuming its essence. This creature, known as a forsaken lich, is granted the undeath it sought in life, but in a terrifyingly temporary fashion. For the miscalculations of its ambitions, the creature's once-vibrant body shrivels and decays like that of a lich, but becomes a lifeless shell manipulated by the malicious soul and unchecked magical storm that envelop it, forces that control the corpse's actions almost like a marionette. Yet this doom is temporary for nearly all who attempt this foul transition. With the soul unbound from the body and both spirit and corpse exposed to destructive arcane tides, both are slowly eroded. After 1d10 days, the forsaken lich's body and soul are both consumed like a lit candle, eventually reduced physically to ashes, and spiritually to nothing-its essence utterly annihilated, scoured from existence for all time.","ecology":"","habitat_society":"","gear":"+1 breastplate, +1 scythe, ring of protection +1"},{"name":"Fossil Golem","cr":12,"xp":19200,"alignment":"N","size":"Huge","type":"construct","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":26,"ac_touch":9,"ac_flat_footed":25,"ac_mods":"+1 Dex, +17 natural, -2 size","hp":122,"hd":"15d10+40","hdvalue":15,"fort":5,"ref":6,"will":5,"dr":"10/adamantine and bludgeoning","immunities":["construct traits","magic"],"speed":[{"type":"land","speed":30}],"melee":"2 bites +20 (6d6+7 plus petrification)","space":"15 ft.","reach":"15 ft.","strength":25,"dexterity":13,"wisdom":10,"charisma":1,"baseatk":15,"cmb":24,"cmd":35,"feats":[{"feat":"Combat Reflexes","type":"bonus"}],"environments":["any"],"organizations":["solitary","gang (2-4)"],"treasure":"none","description_visual":"Fossilized bones make up the body of this animated construct, from its horned shoulders to its tyrannosaur-skulled hands.","group":"Golem","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Immunity to Magic","kind":"Su","details":"A fossil golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and abilities function differently against the creature, as noted below. • A transmute rock to mud spell slows a fossil golem (as the slow spell) for 2d6 rounds, with no saving throw. • A stone to flesh spell negates its damage reduction and petrification ability for 1 round."},{"type":"Petrification","kind":"Su","details":"The attacks of a fossil golem gradually turn living flesh to stone. Each time the golem hits a target with one of its natural attacks, the target must make a DC 19 Fortitude save or take 1d6 points of Dexterity drain. A creature that is reduced to 0 Dexterity by this attack turns completely to stone, as if by a flesh to stone spell. Casting stone to flesh on the creature removes all Dexterity drain caused by this attack. The save DC is Constitution-based and includes a +2 racial bonus."}],"description":"A fossil golem is constructed of the stony bones of long-dead dinosaurs and other prehistoric creatures. These bones are generally not assembled with any attempt to accurately model the original creature-usually, the skulls of powerful predatory dinosaurs (such as tyrannosauruses) serve in the place of hands, granting the fossil golem a pair of devastating bite attacks. The magical energies that infuse a fossil golem create an additional peril-they transform fossilization into a terrible form of contagion that can affect any creature they damage.\n\nFossil golems are often used to guard caverns and other natural fortifications. A fossil golem at rest might look to the untrained eye like nothing more than a strange display of bones. A fossil golem is 20 ft. tall and weighs 8,000 pounds.\n\nConstruction\n\nA fossil golem must be constructed from the fossilized skeletons of at least two creatures of Huge size or greater. The fossilized bone making up the golem requires extensive preservation and reassembly with alchemical solutions at a cost of 5,000 gp.\n\nFOSSIL GOLEM\n\nCL 15th; Price 125,000 gp\n\nConstruction\n\nRequirements Craft Construct, flesh to stone, geas/quest, limited wish, stone shape, creator must be at least caster level 15th; Skill Craft (sculpture) or Heal DC 20; Cost 65,000 gp","ecology":"","habitat_society":""},{"name":"Frost Worm","cr":12,"xp":19200,"alignment":"N","size":"Huge","type":"magical beast","subtypes":["cold"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":27,"ac_touch":11,"ac_flat_footed":24,"ac_mods":"+3 Dex, +16 natural, -2 size","hp":168,"hd":"16d10+80","hdvalue":16,"fort":15,"ref":13,"will":10,"immunities":["cold"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":10}],"melee":"bite +25 (4d10+15 plus 4d6 cold)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"breath weapon","details":"60-ft. cone, 15d6 cold damage, Reflex DC 23 half, usable once per hour"},{"type":"death throes"},{"type":"trill"}],"strength":31,"dexterity":16,"constitution":21,"intelligence":2,"wisdom":16,"charisma":11,"baseatk":16,"cmb":28,"cmd":41,"cmd_special":"can't be tripped","feats":[{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Stand Still"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":17},{"skill":"Stealth","value":6,"special":"+14 in ice and snow"}],"sq":[{"type":"cold"}],"environments":["cold mountains","cold plains"],"organizations":["solitary"],"treasure":"incidental","description_visual":"This immense white worm has a single circular eye in the center of its head. Wisps of icy fog waft up from between its mandibles.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Cold","kind":"Su","details":"A frost worm's body generates intense cold, allowing it to deal an additional 4d6 cold damage with its bite attack. Any creature that attacks a frost worm with an unarmed strike or a natural weapon takes 1d6 points of cold damage per successful hit. A creature that grapples or is grappled by a frost worm takes 4d6 points of cold damage per round the grapple is maintained."},{"type":"Death Throes","kind":"Su","details":"When killed, a frost worm explodes in a 100-foot-radius burst that deals 12d6 cold damage and 8d6 piercing damage (DC 23 Reflex half). The save DC is Constitution-based."},{"type":"Trill","kind":"Su","details":"As a full-round action, a frost worm can emit a strange trilling sound that affects all creatures within a 100-foot radius. Creatures must succeed on a DC 18 Will save or be fascinated for as long as the worm continues to trill (the frost worm can maintain this trill by concentrating). Once a creature has resisted or broken the effect, it cannot be affected again by that same frost worm's trill for 24 hours. This is a sonic mind-affecting effect. The save DC is Charisma-based."}],"description":"With armor-crushing jaws, flesh that radiates cold, and a terrible keening cry capable of holding creatures fascinated, frost worms are apex predators of the frozen tundra and glaciers. In the frost worms' far-reaching hunting grounds, they fear only the remorhaz, for the heat generated by an enraged remorhaz causes intense pain to a frost worm.\n\nThis extreme aversion to heat, as well as its freezing touch and devastating breath weapon, stems from an unusual facet of frost worm physiology-veins that run with magically cold blood. This creature's ichor is clear, but infused with such sub-freezing temperatures that the monster's flesh can freeze water in the skin of creatures that touch it. When a frost worm dies, this magical energy dissipates, and both blood and muscle immediately freeze solid and then explode into a catastrophic barrage of icy shrapnel. As a result, even those predators that might legitimately prey upon the burrowing monstrosities tend to leave frost worms well enough alone.\n\nAn adult frost worm measures 35 ft. long and weighs 8,000 pounds.","ecology":"","habitat_society":""},{"name":"Great Cyclops","cr":12,"xp":19200,"alignment":"CE","size":"Huge","type":"humanoid","subtypes":["giant"],"init":1,"senses":[{"type":"low-light vision"}],"ac":26,"ac_touch":9,"ac_flat_footed":25,"ac_mods":"+4 armor, +1 Dex, +13 natural, -2 size","hp":195,"hd":"17d8+119","hdvalue":17,"fort":12,"ref":6,"will":14,"speed":[{"type":"land","speed":35,"special":"50 ft. without armor"}],"melee":"mwk greatclub +24 (3d8+19), gore +18 (1d8+6) or gore +23 (1d8+13), 2 slams +23 (2d6+13)","ranged":"rock +12 (2d6+19)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"powerful charge","details":"gore, 4d8+24"},{"type":"rock throwing","details":"120 ft."}],"strength":36,"dexterity":13,"constitution":25,"intelligence":7,"wisdom":14,"charisma":8,"baseatk":12,"cmb":27,"cmd":38,"feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Improved Bull Rush"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Sickening Critical"}],"skills":[{"skill":"Perception","value":22}],"languages":["Common","Cyclops","Giant"],"sq":[{"type":"flash of brutality"}],"organizations":["solitary","colony (2-5)","tribe (6-14)"],"treasure":"standard (masterwork greatclub, hide armor)","description_visual":"This misshapen but incredibly muscular humanoid has a single huge bloodshot eye set under a short, jagged horn on its brow.","group":"Cyclops","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Flash of Brutality","kind":"Su","details":"Once per day as a swift action, a great cyclops can gain a burst of savage of inspiration. When it does, it doubles the threat range of all weapons, natural attacks, and rock attacks it makes until the start of its next turn. Furthermore, once per day, when the great cyclops reaches 0 or fewer hit points and is conscious because of its Diehard feat, this ability recharges, allowing it to use the ability a second time that same day."}],"description":"Degenerate giants of cyclops-kind, the legendary great cyclopes embody the rage and dark doom of this race of uncanny seers. In their eyes blaze endless possibilities for bloodshed and terror, their myopic gazes seeming to witness the potential for infinite deaths and devastations hidden within each moment. Gigantic but dull-witted, these massive savages are usually loners, but occasionally either need or fate drives them to rampages from which few are safe. Such undeniable force brings with it a dread that, in many instances, grows to reverence, giving rise to strange cults that cloak these cyclopes with veils of menace and dark legends.\n\nDenizens of remote and primeval parts of the world, great cyclopes typically dwell in lands where none might intrude upon them-deserted islands, high craggy mountains, and stoic hill countries often provide the great caves they favor as lairs. While most avoid well-traveled or populated lands, spending much of their time hunting megafauna and even monstrous prey in the wilds, some, driven by hunger or a desperation to wander, seek out the paths and settlements of humanoids, finding that their fragile buildings are easily shattered and that the mewling creatures make savory meals.\n\nThe average great cyclops stands approximately 30 ft. tall and weighs upward of 4 tons, though individuals of significantly greater size are known.","ecology":"","habitat_society":""},{"name":"Heresy Devil (Ayngavhaul)","cr":12,"xp":19200,"alignment":"LE","size":"Huge","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see in darkness"}],"ac":29,"ac_touch":7,"ac_flat_footed":29,"ac_mods":"+4 armor, -1 Dex, +18 natural, -2 size","hp":175,"hd":"13d10+104","hdvalue":13,"hp_mods":["fast healing 5"],"fort":17,"ref":3,"will":13,"dr":"5/good","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":22,"speed":[{"type":"land","speed":10},{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"2 slams +18 (2d8+7), bite +18 (2d6+7)","ranged":"searing word +10 (3d6)","space":"15 ft.","reach":"5 ft.","special_attacks":[{"type":"blasphemous bile"},{"type":"summon devil"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":20,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"deathwatch"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"illusory script"},{"spell":"mage hand"},{"spell":"major image"},{"spell":"message"}]},{"frequency":"1/day","spells":[{"spell":"blasphemy"},{"spell":"legend lore"},{"spell":"mislead"},{"spell":"unhallow"}]},{"frequency":"3/day","spells":[{"spell":"contagion"},{"spell":"deeper darkness"},{"spell":"dispel good"},{"spell":"dispel magic"},{"spell":"invisibility purge"},{"spell":"magic circle against good"},{"spell":"speak with dead"},{"spell":"stinking cloud"},{"spell":"summon monster V"},{"spell":"telekinesis"},{"spell":"unholy blight"},{"spell":"zone of silence"}]}],"strength":24,"dexterity":8,"constitution":24,"intelligence":22,"wisdom":21,"charisma":20,"baseatk":13,"cmb":18,"cmd":37,"feats":[{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Persuasive"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":21},{"skill":"Diplomacy","value":25},{"skill":"Fly","value":8},{"skill":"Intimidate","value":17},{"skill":"Knowledge (arcana)","value":22},{"skill":"Knowledge (history)","value":19},{"skill":"Knowledge (planes)","value":22},{"skill":"Knowledge (religion)","value":22},{"skill":"Perception","value":21},{"skill":"Perform (oratory)","value":18},{"skill":"Profession (librarian)","value":10},{"skill":"Sense Motive","value":21},{"skill":"Spellcraft","value":22}],"languages":["Abyssal","Celestial","Draconic","Infernal"],"sq":[{"type":"corpulence"},{"type":"devil summoner"},{"type":"throne of skulls"}],"environments":["any (Hell)"],"organizations":["solitary","pair","lecture (3-8)"],"treasure":"standard","description_visual":"Seemingly fused with a monstrous throne of iron skulls, this impossibly corpulent being floats several ft. off the ground. Trappings cut in mockery of holy vestments do little to cover the thing's pallid, leaking rolls of blister-pocked girth. Worthless, clublike hands waggle like maggots, directing a cloud of weathered scrolls and blasphemous tomes that orbit its bulk. Barely distinguishable amid its mound of chins squints a pair of glassy black eyes, riding above a disproportionately wide mouth curled into a perpetually lecherous grin.","group":"Devil","source":"Book of the Damned V1","special_abilities":[{"type":"Corpulence","kind":"Ex","details":"Ayngavhauls are greasy and grossly obese. This extraordinary bulk provides them with a +10 bonus on their combat maneuver defense."},{"type":"Blasphemous Bile","kind":"Su","details":"30-ft. line, once every 1d4 hours; damage 4d6 acid, Reflex DC 23 half. Those struck by this bile find themselves drenched in liquid corruption so profound it impedes the power of non-evil divine magic for 10 minutes. Any non-evil divine spellcaster who casts a spell targeting a creature soaked in an ayngavhaul's bile must make a DC 23 caster level check or have the spell fail. A creature affected by this bile may wash off the sludge by spending a round and using at least a gallon of fluid to cleanse itself. The save DC is Constitution-based."},{"type":"Devil Summoner","kind":"Su","details":"Ayngavhauls know the secrets of all breeds of devils, utilizing such leverage in the summoning of their kind. Any devil within 30 ft. of an ayngavhaul has half again the normal chance of having a fiend respond to its summon devil ability. For example, an osyluth's usual 35% chance to summon another bone devil increases to 52% when within 30 ft. of an ayngavhaul. Summoning bonuses provided by multiple ayngavahuls don't stack. Ayngavahuls are immune to this ability, from both themselves and others of their kind."},{"type":"Searing Word","kind":"Su","details":"An ayngavhaul can speak words of torment, giving them shape and sending them streaking toward their enemies in the form of diabolical sigils. Any good-aligned creature struck by one of these infernal words takes 3d6 points of hellfire damage (half fire, half evil energy); nongood creatures take half damage. These words cannot affect creatures affected by protection from evil or within an area of magical silence."},{"type":"Summon Devil","kind":"Sp","details":"Once per day an ayngavhaul can attempt to summon 2d6 imps, 1d4 bearded devils, or 2 bone devils with an 80% chance of success, or a contract devil with a 45% chance of success. This ability is the equivalent of a 6th-level spell."},{"type":"Throne of Skulls","kind":"Su","details":"All ayngavhauls hover upon fearsome infernal thrones. These thrones grant the devils their fly speed and a +4 armor bonus. Should an ayngavhaul be grappled or knocked down, it is unseated from its throne and loses these benefits. An ayngavhaul has telepathic command over its throne and may call its conveyance back and reseat itself as a full-round action."}],"description":"Bloated scholars of despair, ayngavhauls collect, create, and spread heresies and apocrypha, sowing disbelief and corruption to all who would seek their foul wisdom. Ironically among the most humanlike, yet still most repulsive breeds of devilkind, these corpulent blasphemers are barely even able to move without the aid of their profane floating thrones. Although their bloated forms make them considerably less of a threat than their brethren physically, they speak maledictions foul enough to agonize those who hear them, yet even with such powers of vicious wisdom, their true strength lies in their envenomed words and temptations of the mind. Their centuries of research grant them great leverage over their diabolical kin, and few devils dare not obey the summons of these hellish scholars. Ayngavhauls are roughly ovular in form, their def lated girths about 10 ft. tall with their rolls of wet gristle spreading over 13 ft. wide. Off their thrones, these devils weigh approximately 2,300 pounds, though the eldest can weigh considerably more. Ecology Ayngavhauls' bloated girths make them slaves to their repulsive physical forms. All ayngavhauls, even the newly formed, are monstrously obese, trapped within prisons of their own leaking, diabolical flesh. To aid them, though, the forges of Phlegethon create terrifying thrones empowered by infernal magics. These foul chariots hold their corpulent masters aloft, serving as both vehicles and sources of profane protection. Each throne of skulls is bound to a specific ayngavhaul, dissolving into a pile of ashes and a breath of searing iron dust should its master be destroyed. Habitat & Society The majority of ayngavhuals frequent the grim libraries of Hell, particularly the mired museums of Stygia; the Fallen Fastness of Dis; and Betzebbul, the palace of Baalzebul, in Cocytus. Within these heretical storehouses and academies of evil, these grotesque devils rewrite the histories of countless worlds to obscure truths and skew the past toward the desires of Hell. Grotesque curators of a sort, individual ayngavhauls take great pride in specializing in fields none of their brethren have ever thought to focus their studies upon-the more obscure and blasphemous, the better. Thus, while one devil might spend eons learning all there is to know of linnorm frost poisons, another might research the nuances of Azlanti voice tearing. Each seeks to promote its particular field of research above all others, sowing its knowledge among their blasphemous works, minions, and summoners who might put such foul wisdom to the most sinister uses. They prove incessantly paranoid that the works of their brethren might be outstripping their own discoveries, or that others in related fields might be stealing their research, thus proving both suspicious of their kindred and intimately familiar with the works of other infernal scholars. As such, a single ayngavhaul might begrudgingly point a summoner in search of specific information toward a diabolical expert, though these knowledge-obsessed fiends never reveal their secrets without demanding a price.","ecology":"Ayngavhauls' bloated girths make them slaves to their repulsive physical forms. All ayngavhauls, even the newly formed, are monstrously obese, trapped within prisons of their own leaking, diabolical flesh. To aid them, though, the forges of Phlegethon create terrifying thrones empowered by infernal magics. These foul chariots hold their corpulent masters aloft, serving as both vehicles and sources of profane protection. Each throne of skulls is bound to a specific ayngavhaul, dissolving into a pile of ashes and a breath of searing iron dust should its master be destroyed.","habitat_society":"The majority of ayngavhuals frequent the grim libraries of Hell, particularly the mired museums of Stygia; the Fallen Fastness of Dis; and Betzebbul, the palace of Baalzebul, in Cocytus. Within these heretical storehouses and academies of evil, these grotesque devils rewrite the histories of countless worlds to obscure truths and skew the past toward the desires of Hell. Grotesque curators of a sort, individual ayngavhauls take great pride in specializing in fields none of their brethren have ever thought to focus their studies upon-the more obscure and blasphemous, the better. Thus, while one devil might spend eons learning all there is to know of linnorm frost poisons, another might research the nuances of Azlanti voice tearing. Each seeks to promote its particular field of research above all others, sowing its knowledge among their blasphemous works, minions, and summoners who might put such foul wisdom to the most sinister uses. They prove incessantly paranoid that the works of their brethren might be outstripping their own discoveries, or that others in related fields might be stealing their research, thus proving both suspicious of their kindred and intimately familiar with the works of other infernal scholars. As such, a single ayngavhaul might begrudgingly point a summoner in search of specific information toward a diabolical expert, though these knowledge-obsessed fiends never reveal their secrets without demanding a price."},{"name":"Hetkoshu","cr":12,"xp":19200,"alignment":"N","size":"Gargantuan","type":"animal","init":4,"senses":[{"type":"low-light vision"}],"ac":25,"ac_touch":6,"ac_flat_footed":25,"ac_mods":"+19 natural, -4 size","hp":172,"hd":"15d8+105","hdvalue":15,"fort":16,"ref":9,"will":11,"speed":[{"type":"land","speed":20},{"type":"swim","speed":30}],"melee":"bite +23 (3d6+15/19-20 plus grab), tail slap +17 (4d8+7)","space":"20 ft.","reach":"15 ft.","special_attacks":[{"type":"death roll","details":"3d6+15 plus trip"},{"type":"fast swallow"},{"type":"savage rush"},{"type":"swallow whole","details":"3d6+15 bludgeoning damage, AC 19, 17 hp"}],"strength":40,"dexterity":10,"constitution":25,"intelligence":1,"wisdom":18,"charisma":7,"baseatk":11,"cmb":30,"cmd":40,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Run"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":15},{"skill":"Stealth","value":11,"special":"+19 in water"},{"skill":"Swim","value":23}],"sq":[{"type":"hold breath"}],"environments":["warm marshes","warm rivers"],"organizations":["solitary","pair","colony (3-6)"],"treasure":"none","description_visual":"This enormous black crocodile gapes hungrily with a maw big enough to swallow two armored warriors whole.","group":"Crocodile","source":"Osirion, Legacy Of Pharaohs","special_abilities":[{"type":"Death Roll","kind":"Ex","details":"Upon making a successful grapple check against a foe of its size or smaller, a hetkoshu deals bite damage to the target and knocks it prone. This doesn't break the hetkoshu's grapple."},{"type":"Hold Breath","kind":"Ex","details":"A hetkoshu can hold its breath for 4 rounds per point of Constitution before having to make Constitution checks to continue holding its breath."},{"type":"Savage Rush","kind":"Ex","details":"For 1 round per minute, a hetkoshu may sprint with devastating speed, increasing its land speed to 40 ft. and allowing it to treat nonmagical difficult terrain as if it were normal terrain. If it charges during this round, it may attack twice with its bite as its attack action, using the same attack modifier for both attacks."}],"description":"Infamous along Osirion's major rivers as well as in the Golden Oasis near Shiman-Sekh, hetkoshus are among the most dangerous animals on Garund. They pose a constant threat to travelers and those who make their livelihoods along these waterways. Hetkoshus wait for prey to pass within 90 ft. before rushing at them to gobble up one or two opponents in a single terrible motion, preferably before the prey even realizes any danger exists. They are known for their feared \"death roll\"-once one clings to its foe, it tucks in its legs and rolls rapidly, twisting and wrenching its victim.\n\nHetkoshus average 30 ft. in length and weigh nearly 45,000 pounds.","ecology":"","habitat_society":""}];
